css:
.nebula-pattern {
  position: relative;
  width: 100%;
  height: 100%;
  background: linear-gradient(125deg, #1a0a2d 0%, #3542c4 65%, #ffdee9 100%);
  overflow: hidden;
  box-shadow: 0 4px 24px rgba(40, 20, 80, 0.12);
}

.nebula {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  filter: url(#iridescent-nebula);
  background: radial-gradient(
      circle at 75% 60%,
      rgba(255, 246, 203, 0.16) 0,
      transparent 90%
    ),
    radial-gradient(
      circle at 28% 22%,
      rgba(225, 129, 255, 0.23) 0,
      transparent 65%
    ),
    radial-gradient(
      circle at 60% 80%,
      rgba(31, 255, 250, 0.13) 0,
      transparent 80%
    );
  mix-blend-mode: lighten;
  z-index: 2;
}
